// El flujo tiene dos entradas POST:
//   - POST /apartar-zapatos      : el cliente envia la solicitud
//   - POST /confirmar-solicitud : la tienda confirma cuando llega el abono inicial
const entrada = $input.first().json ?? {};
const cuerpo = entrada.body ?? {};
const codigo = String(cuerpo.codigo ?? cuerpo.codigo_solicitud ?? '').trim();

return [{
  json: {
    ...entrada,
    camino: codigo ? 'confirmar' : 'solicitud',
    datos: cuerpo,
    codigo,
  },
}];

// Busca la solicitud por su codigo. Si no existe o ya estaba confirmada, no hay
// nada que hacer (para no crear dos veces el mismo apartado).
const entrada = $input.first().json ?? {};
const codigo = String(entrada.codigo ?? '').trim();

const staticData = $getWorkflowStaticData('global');
staticData.solicitudes = staticData.solicitudes ?? {};
const solicitud = staticData.solicitudes[codigo] ?? null;

const pendiente = Boolean(solicitud) && solicitud.estado === 'pendiente';

return [{
  json: {
    ...entrada,
    solicitud: pendiente ? solicitud : null,
    encontrada: Boolean(solicitud),
    pendiente,
  },
}];

// Crea el apartado en la app, con la fecha original y el abono inicial recibido.
const entrada = $input.first().json ?? {};
const s = entrada.solicitud ?? {};
// El importe llega en el cuerpo del webhook de confirmacion.
const importe = Number(entrada.datos?.importe ?? entrada.importe ?? entrada.abono_inicial ?? 0);

return [{
  json: {
    ...entrada,
    importe: Number.isFinite(importe) ? importe : 0,
    apartado: {
      cliente: s.cliente,
      telefono: s.telefono,
      email: s.email,
      producto: s.producto,
      talla: s.talla,
      precio: s.precio,
      abono_inicial: Number.isFinite(importe) ? importe : 0,
      forma_pago: s.forma_pago ?? 'bizum',
      fecha: s.fecha,
    },
  },
}];

// Marca la solicitud como confirmada y avisa al cliente y a la tienda.
const entrada = $input.first().json ?? {};
const creado = entrada;
const solicitud = entrada.solicitud ?? {};
const codigo = String(solicitud.codigo ?? entrada.codigo ?? '');

const staticData = $getWorkflowStaticData('global');
staticData.solicitudes = staticData.solicitudes ?? {};
if (staticData.solicitudes[codigo]) {
  staticData.solicitudes[codigo].estado = 'confirmada';
  staticData.solicitudes[codigo].apartado_id = creado.id ?? null;
}

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';

const cuerpoCliente = [
  'Hola ' + (solicitud.cliente ?? '') + ',',
  '',
  'Tu apartado de ' + (solicitud.producto ?? '') + (solicitud.talla ? ' · talla ' + solicitud.talla : '') + ' esta confirmado.',
  '',
  'Abonado: ' + euros(entrada.importe),
  'Te queda por pagar: ' + euros((creado.precio ?? 0) - (entrada.importe ?? 0)),
  'Fecha limite: ' + (creado.fecha_limite ?? ''),
  '',
  'Cuando quieras puedes pasar por la tienda a pagar el resto.',
  '',
  'Zapateria Paso Firme',
].join('\n');

const cuerpoTienda = [
  'Apartado confirmado: ' + (solicitud.producto ?? '') + ' de ' + (solicitud.cliente ?? '') + '.',
  'Abono inicial: ' + euros(entrada.importe),
  'Codigo de la solicitud: ' + codigo,
].join('\n');

return [{
  json: {
    ...entrada,
    cuerpo_cliente: cuerpoCliente,
    cuerpo_tienda: cuerpoTienda,
  },
}];

// Aviso a la tienda: la solicitud no existe o ya estaba confirmada.
const entrada = $input.first().json ?? {};
const codigo = String(entrada.codigo ?? '');
const cuerpo = [
  'No se ha podido confirmar la solicitud ' + (codigo || '(sin codigo)') + '.',
  entrada.encontrada ? 'Ya estaba confirmada antes.' : 'No existe ninguna solicitud con ese codigo.',
].join('\n');

return [{ json: { ...entrada, cuerpo_tienda: cuerpo, cuerpo_cliente: '' } }];

// Crea la solicitud de apartado: el cliente ha pedido apartar unos zapatos desde
// casa, pero todavia no ha pagado el abono inicial.
//
// La solicitud se guarda en los datos estaticos del flujo (la memoria de n8n entre
// ejecuciones) con un codigo para que la tienda pueda confirmarla.
const entrada = $input.first().json ?? {};
const datos = entrada.datos ?? entrada;

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const precio = Number(String(datos.precio ?? '').replace(',', '.'));
const digitos = (s) => String(s ?? '').replace(/[^0-9]/g, '');

const staticData = $getWorkflowStaticData('global');
staticData.solicitudes = staticData.solicitudes ?? {};
staticData.contador = (staticData.contador ?? 0) + 1;

const codigo = 'SOL-' + String(staticData.contador).padStart(4, '0');
const solicitud = {
  codigo,
  cliente: String(datos.cliente ?? '').trim(),
  telefono: digitos(datos.telefono),
  email: String(datos.email ?? '').trim(),
  producto: String(datos.producto ?? '').trim(),
  talla: String(datos.talla ?? '').trim(),
  precio: Number.isFinite(precio) ? precio : 0,
  forma_pago: String(datos.forma_pago ?? 'bizum').trim().toLowerCase(),
  fecha: new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
  }).format(new Date()),
  estado: 'pendiente',
};

staticData.solicitudes[codigo] = solicitud;

const cuerpo = [
  'Un cliente quiere apartar unos zapatos desde casa:',
  '',
  'Codigo de la solicitud: ' + codigo,
  'Cliente: ' + (solicitud.cliente || '(sin nombre)'),
  'Telefono: ' + (solicitud.telefono || '(sin telefono)'),
  'Correo: ' + (solicitud.email || '(sin correo)'),
  'Producto: ' + solicitud.producto + (solicitud.talla ? ' · talla ' + solicitud.talla : ''),
  'Precio: ' + euros(solicitud.precio),
  'Paga con: ' + solicitud.forma_pago,
  '',
  'Cuando llegue el abono inicial, confirma la solicitud con:',
  'POST /webhook/confirmar-solicitud  { "codigo": "' + codigo + '", "importe": 10 }',
  '',
  'El apartado NO se ha creado todavia: solo es una solicitud.',
].join('\n');

return [{
  json: {
    ...entrada,
    solicitud,
    codigo,
    cuerpo,
  },
}];

// Mensaje para la tienda con la solicitud nueva.
const entrada = $input.first().json ?? {};
return [{ json: { ...entrada, cuerpo: entrada.cuerpo ?? '' } }];

// Mensaje para el cliente: el apartado ya esta confirmado.
const entrada = $input.first().json ?? {};
return [{ json: { ...entrada, cuerpo: entrada.cuerpo_cliente ?? '' } }];

