<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Apartar unos zapatos · Paso Firme</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 0; background: #f6f4f1; color: #26221e; }
  main { max-width: 460px; margin: 3rem auto; padding: 2rem; background: #fff; border-radius: 12px;
         box-shadow: 0 6px 24px rgba(0,0,0,.08); }
  h1 { font-size: 1.4rem; margin-top: 0; }
  label { display: block; margin: 1rem 0 .25rem; font-weight: 600; font-size: .9rem; }
  input { width: 100%; padding: .6rem .7rem; border: 1px solid #ccc; border-radius: 8px; font-size: 1rem; }
  button { margin-top: 1.4rem; width: 100%; padding: .8rem; font-size: 1rem; border: 0; border-radius: 8px;
           background: #2f6f4f; color: #fff; cursor: pointer; }
  .nota { font-size: .85rem; color: #666; margin-top: 1rem; }
  .error { color: #a33; margin-top: 1rem; }
</style>
</head>
<body>
<main>
  <h1>Apartar unos zapatos</h1>
  <p>Rellena estos datos. El apartado se confirma cuando llegue el abono inicial.</p>
  <form id="form">
    <label for="cliente">Tu nombre</label>
    <input id="cliente" name="cliente" required>
    <label for="telefono">Tu teléfono (9 dígitos)</label>
    <input id="telefono" name="telefono" required>
    <label for="email">Tu correo</label>
    <input id="email" name="email" type="email">
    <label for="producto">Qué quieres apartar</label>
    <input id="producto" name="producto" required>
    <label for="talla">Talla</label>
    <input id="talla" name="talla">
    <label for="precio">Precio en euros</label>
    <input id="precio" name="precio" type="number" step="0.01" required>
    <label for="forma_pago">Cómo vas a pagar</label>
    <input id="forma_pago" name="forma_pago" value="bizum">
    <button type="submit">Enviar la solicitud</button>
  </form>
  <p class="nota">La tienda te avisa cuando llegue el abono inicial.</p>
  <p class="error" id="error" hidden></p>
</main>
<script>
  document.getElementById('form').addEventListener('submit', async (evento) => {
    evento.preventDefault();
    const datos = Object.fromEntries(new FormData(evento.target).entries());
    try {
      const r = await fetch(location.pathname, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(datos),
      });
      const texto = await r.text();
      document.querySelector('main').innerHTML = '<h1>Gracias</h1><p>' + texto + '</p>';
    } catch (e) {
      const aviso = document.getElementById('error');
      aviso.hidden = false;
      aviso.textContent = 'No se ha podido enviar. Llama a la tienda.';
    }
  });
</script>
</body>
</html>
</html>

